// Reduce OCR text size before the extraction LLM call so we stay under
// Groq's tokens-per-minute (TPM) limit. Marksheets are mostly short lines +
// numbers; most tokens are wasted whitespace and layout noise from OCR.

// Cap so prompt + text stays well under the 8000 TPM window.
const MAX_CHARS = 5000;

return items.map(item => {
    const src = $('Parse OCR Result1').item.json;
    let text = (src && src.extractedText) || '';

    text = text
        // normalize newlines
        .replace(/\r\n?/g, '\n')
        // collapse runs of spaces/tabs into a single space
        .replace(/[ \t]{2,}/g, ' ')
        // strip trailing spaces on each line
        .replace(/[ \t]+\n/g, '\n')
        // collapse 3+ blank lines into a single blank line
        .replace(/\n{3,}/g, '\n\n')
        // drop lines that carry no letters or digits (pure separators/symbols)
        .split('\n')
        .filter(line => /[A-Za-z0-9]/.test(line))
        .join('\n')
        .trim();

    let truncated = false;
    if (text.length > MAX_CHARS) {
        text = text.slice(0, MAX_CHARS);
        truncated = true;
    }

    return {
        json: {
            cleanedText: text,
            cleanedCharCount: text.length,
            originalCharCount: (src && src.charCount) || 0,
            truncated,
            documentType: $('Classify Document1').item.json.output.document_type
        }
    };
});

