const results = [];

for (const item of items) {
    const binary = item.binary || {};

    const firstKey = Object.keys(binary)[0];
    const file = firstKey ? binary[firstKey] : null;

    const mime = file?.mimeType || "";

    let fileType = "unsupported";

    if (mime === "application/pdf") {
        fileType = "pdf";
    } else if (mime.startsWith("image/")) {
        fileType = "image";
    }

    // Normalize the uploaded file to a fixed binary key "file"
    // so the OCR HTTP node can reference it reliably.
    results.push({
        json: {
            fileType,
            mimeType: mime,
            fileName: file?.fileName || ""
        },
        binary: file ? { file } : {}
    });
}

return results;

// =========================
// Supported Document Types
// =========================

const documentTypes = [

  // Identity
  "Aadhaar Card",
  "PAN Card",
  "Passport",
  "Driving License",
  "Voter ID",
  "Employee ID Card",
  "Student ID Card",

