  "Form 16",
  "Income Tax Return",

  // Government
  "Birth Certificate",
  "Death Certificate",
  "Marriage Certificate",
  "Income Certificate",
  "Caste Certificate",
  "Domicile Certificate",

  // Utility
  "Electricity Bill",
  "Water Bill",
  "Gas Bill",
  "Telephone Bill",
  "Internet Bill",

  // Medical
  "Medical Report",
  "Prescription",
  "Lab Report",
  "Discharge Summary",

  // Insurance
  "Insurance Policy",
  "Insurance Claim",

  // Legal
  "Contract",
  "Agreement",
  "Non-Disclosure Agreement (NDA)",
  "Affidavit",
  "Court Order",

  // Travel
  "Flight Ticket",
  "Train Ticket",
  "Bus Ticket",
  "Boarding Pass",
  "Hotel Booking",

  // Other
  "Unknown"
];

return items.map(item => {

    const resp = item.json || {};

    let text = '';

    if (resp.type === 'pdf') {
        text = resp.full_text || '';
    } else if (resp.type === 'image') {
        text = resp.text || '';
    } else {
        text =
            resp.full_text ||
            resp.text ||
            (Array.isArray(resp.lines)
                ? resp.lines.join('\n')
                : '');
    }

    return {
        json: {
            extractedText: text.trim(),
            documentTypes,
            sourceType: resp.type || 'unknown',
            totalPages: resp.total_pages || 1,
            charCount: text.trim().length
        }
    };

});
